#!/usr/bin/env bash
# init.sh — standard startup and verification path for gateway.
# Generated by the agent-workspace harness on 2026-05-25.
# Edit INSTALL_CMD / VERIFY_CMD / START_CMD freely; keep the overall shape.

set -euo pipefail

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$ROOT_DIR"

# Repo-specific notes:
# Gateway needs FoundationDB client libs (v6.2.27). Runtime requires Redis + etcd + Discord TOKEN. The verify command runs a build only — full tests require infra.

INSTALL_CMD=(bash -c 'go mod download')
VERIFY_CMD=(bash -c 'go build ./...')
START_CMD=(bash -c '(cd cmd/gateway && go run .)')

echo "==> Working directory: $PWD"
echo "==> Syncing dependencies"
"${INSTALL_CMD[@]}"

echo "==> Running baseline verification"
"${VERIFY_CMD[@]}"

echo "==> Startup command"
printf '    '; printf '%q ' "${START_CMD[@]}"; echo

if [ "${RUN_START_COMMAND:-0}" = "1" ]; then
  echo "==> Starting the app"
  exec "${START_CMD[@]}"
fi

echo "Set RUN_START_COMMAND=1 if you want init.sh to launch the app directly."
